import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.PlayerToggleCrafterSlotRequest{PosX: 1, PosY: -2, PosZ: 300, Slot: 200, Disabled: true}
DISABLED = bytes.fromhex("01000000feffffff2c010000c801")

# generated by gophertunnel b8bd735:
# packet.PlayerToggleCrafterSlotRequest{}
ZERO = bytes.fromhex("0000000000000000000000000000")

GOLDENS = [
    pytest.param(
        v2225.PlayerToggleCrafterSlotRequestPacket(pos_x=1, pos_y=-2, pos_z=300, slot_index=200, is_disabled=True),
        DISABLED,
        id="disabled",
    ),
    pytest.param(v2225.PlayerToggleCrafterSlotRequestPacket(), ZERO, id="zero"),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_player_toggle_crafter_slot_request_is_packet_306(version):
    assert version.PACKETS[306] is version.PlayerToggleCrafterSlotRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_toggle_crafter_slot_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_toggle_crafter_slot_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_player_toggle_crafter_slot_request_rejects_a_varint_body():
    with pytest.raises(ValueError, match="at byte"):
        v2225.PlayerToggleCrafterSlotRequestPacket.from_bytes(bytes.fromhex("0203a804c80101"))
